INSERT INTO content_releases VALUES('grade4-tense-v1','published','ee5fdc0afcedc0c9ec6091442e00851882131f638a59a1548685b58e8359fff6',unixepoch()*1000);
INSERT INTO lessons VALUES
('P4A-U01-L1',2,'grade4-tense-v1',4,'A',1,'每天的习惯有规律','{"id":"P4A-U01-L1","unitId":"P4A-U01","unitTitle":"新学期新目标","grade":4,"term":"A","order":1,"minutes":6,"title":"每天的习惯有规律","subtitle":"用一般现在时说日常。","topicIds":["tense.present-simple"],"vocabulary":[{"word":"usually","meaning":"通常"},{"word":"study","meaning":"学习"},{"word":"school","meaning":"学校"}],"task":"写出一个真实的小习惯，再把主语换成一个朋友试试看。","cards":[{"title":"看清时间与结构","example":"I walk to school every day.","translation":"我每天步行上学。","rule":"every day说明习惯，用一般现在时。I后用walk；换成she，walk变walks。"},{"title":"换一种表达","example":"She walks to school every day.","translation":"她每天步行上学。","rule":"一般现在时的肯定句中，he、she、it后的实义动词通常用三单形式。"},{"title":"每天的习惯有规律","rule":"日常习惯用一般现在时。主语是he、she或一个人的名字时，肯定句中的行为动词常要加-s或-es。","example":"Mia walks to school every day.","translation":"Mia每天步行上学。"},{"title":"每天的习惯有规律","rule":"日常习惯用一般现在时。主语是he、she或一个人的名字时，肯定句中的行为动词常要加-s或-es。","example":"I read every day.","translation":"我每天阅读。"},{"title":"每天的习惯有规律","rule":"日常习惯用一般现在时。主语是he、she或一个人的名字时，肯定句中的行为动词常要加-s或-es。","example":"Ben studies English on Sundays.","translation":"Ben每逢周日学英语。"}],"itemCount":9,"version":2,"releaseId":"grade4-tense-v1"}'),
('P4A-U01-L2',2,'grade4-tense-v1',4,'A',1,'频率词站在哪里','{"id":"P4A-U01-L2","unitId":"P4A-U01","unitTitle":"新学期新目标","grade":4,"term":"A","order":2,"minutes":6,"title":"频率词站在哪里","subtitle":"用usually、often和never说频率。","topicIds":["grammar.frequency"],"vocabulary":[{"word":"often","meaning":"经常"},{"word":"always","meaning":"总是"},{"word":"never","meaning":"从不"}],"task":"说说你经常做的一件事，保留一个符合真实情况的频率词。","cards":[{"title":"看清时间与结构","example":"I am usually early.","translation":"我通常很早到。","rule":"频率副词usually通常放在be动词后：am usually。"},{"title":"换一种表达","example":"I usually arrive early.","translation":"我通常很早到。","rule":"在普通肯定句中，usually通常放在实义动词arrive前，不是所有动词后都放usually。"},{"title":"频率词站在哪里","rule":"频率副词常放在行为动词前、be动词后，例如usually read、am never late。","example":"I often read at home.","translation":"我经常在家阅读。"},{"title":"频率词站在哪里","rule":"频率副词常放在行为动词前、be动词后，例如usually read、am never late。","example":"I am never late.","translation":"我从不迟到。"},{"title":"频率词站在哪里","rule":"频率副词常放在行为动词前、be动词后，例如usually read、am never late。","example":"Ben usually gets up early.","translation":"Ben通常早起。"}],"itemCount":9,"version":2,"releaseId":"grade4-tense-v1"}'),
('P4A-U01-L3',2,'grade4-tense-v1',4,'A',1,'问问朋友的小习惯','{"id":"P4A-U01-L3","unitId":"P4A-U01","unitTitle":"新学期新目标","grade":4,"term":"A","order":3,"minutes":6,"title":"问问朋友的小习惯","subtitle":"does出现后，行为动词回原形。","topicIds":["sentence.yes-no","tense.present-simple"],"vocabulary":[{"word":"practice","meaning":"练习"},{"word":"early","meaning":"早早地"},{"word":"every","meaning":"每一"}],"task":"问家长一个真实的习惯问题，并留意do或does后面的动词。","cards":[{"title":"看清时间与结构","example":"Does Mia read after dinner?","translation":"Mia晚饭后读书吗？","rule":"主语是Mia，用Does提问；后面的read用原形，不能写reads。"},{"title":"换一种表达","example":"Mia does not read after dinner.","translation":"Mia晚饭后不读书。","rule":"does not / doesn''t已经表示主语的变化，后面的实义动词用原形。"},{"title":"问问朋友的小习惯","rule":"一般现在时中，I和you用do提问；he、she或单个人名用does。does后面的行为动词用原形。","example":"Does Mia read every day?","translation":"Mia每天阅读吗？"},{"title":"问问朋友的小习惯","rule":"一般现在时中，I和you用do提问；he、she或单个人名用does。does后面的行为动词用原形。","example":"Do you get up early?","translation":"你早起吗？"},{"title":"问问朋友的小习惯","rule":"一般现在时中，I和you用do提问；he、she或单个人名用does。does后面的行为动词用原形。","example":"Ben does not swim on Sundays.","translation":"Ben周日不游泳。"}],"itemCount":9,"version":2,"releaseId":"grade4-tense-v1"}'),
('P4A-U01-L4',2,'grade4-tense-v1',4,'A',1,'读懂一份学习日志','{"id":"P4A-U01-L4","unitId":"P4A-U01","unitTitle":"新学期新目标","grade":4,"term":"A","order":4,"minutes":6,"title":"读懂一份学习日志","subtitle":"从日志里找到时间线索和动词伙伴。","topicIds":["tense.present-simple","grammar.frequency"],"vocabulary":[{"word":"goal","meaning":"目标"},{"word":"diary","meaning":"日记"},{"word":"Monday","meaning":"星期一"}],"task":"为自己选一个小学习目标，用一句真实的英语习惯句描述。","cards":[{"title":"看清时间与结构","example":"I read comics on Saturdays.","translation":"我每周六读漫画。","rule":"on Saturdays表示反复发生的周六习惯；read这里是原形，读/riːd/。"},{"title":"换一种表达","example":"I am reading a comic now.","translation":"我现在正在读一本漫画。","rule":"now配合这里正在进行的情境，用am reading。习惯和此刻正在做的事要分开。"},{"title":"读懂一份学习日志","rule":"every day、on Mondays等线索常描述习惯，但还要结合整句意思判断，不是只看一个词。","example":"I read at home every day.","translation":"我每天在家阅读。"},{"title":"读懂一份学习日志","rule":"every day、on Mondays等线索常描述习惯，但还要结合整句意思判断，不是只看一个词。","example":"Mia often plays the piano on Mondays.","translation":"Mia经常在周一弹钢琴。"},{"title":"读懂一份学习日志","rule":"every day、on Mondays等线索常描述习惯，但还要结合整句意思判断，不是只看一个词。","example":"I usually start early.","translation":"我通常很早开始。"}],"itemCount":9,"version":2,"releaseId":"grade4-tense-v1"}'),
('P4A-U02-L1',2,'grade4-tense-v1',4,'A',2,'昨天的was和were','{"id":"P4A-U02-L1","unitId":"P4A-U02","grade":4,"term":"A","order":5,"unitLesson":1,"unitNumber":2,"minutes":7,"title":"昨天的was和were","subtitle":"回想昨天一件小事，用I was…说说当时的状态。","topicIds":["tense.past-simple","grammar.be"],"vocabulary":[{"word":"yesterday","meaning":"昨天"},{"word":"was","meaning":"过去的am/is"},{"word":"were","meaning":"过去的are"}],"task":"回想昨天一件小事，用I was…说说当时的状态。","unitTitle":"过去的周末","releaseId":"grade4-tense-v1","cards":[{"title":"看清时间与结构","example":"I was at the sports centre yesterday.","translation":"我昨天在体育中心。","rule":"说过去的位置，I用was；这句话没有实义动词动作，不用did。"},{"title":"换一种表达","example":"We were at the sports centre yesterday.","translation":"我们昨天在体育中心。","rule":"过去的be要看主语：I/he/she/it用was，you/we/they用were。"},{"title":"昨天的was和were","rule":"描述过去的状态，I/he/she/it和单个人物常用was，you/we/they常用were。先确认说的是过去，再看主语。","example":"She was excited yesterday.","translation":"她昨天很兴奋。"},{"title":"昨天的was和were","rule":"描述过去的状态，I/he/she/it和单个人物常用was，you/we/they常用were。先确认说的是过去，再看主语。","example":"They were quiet last night.","translation":"他们昨晚很安静。"},{"title":"昨天的was和were","rule":"描述过去的状态，I/he/she/it和单个人物常用was，you/we/they常用were。先确认说的是过去，再看主语。","example":"You were busy on Sunday.","translation":"你周日很忙。"}],"itemCount":9,"version":2}'),
('P4A-U02-L2',2,'grade4-tense-v1',4,'A',2,'上周末，你在哪里','{"id":"P4A-U02-L2","unitId":"P4A-U02","grade":4,"term":"A","order":6,"unitLesson":2,"unitNumber":2,"minutes":7,"title":"上周末，你在哪里","subtitle":"和家长互相说说上周末去过哪里，不必去过远方才有故事。","topicIds":["tense.past-simple","grammar.prepositions"],"vocabulary":[{"word":"library","meaning":"图书馆"},{"word":"garden","meaning":"花园"},{"word":"home","meaning":"家"}],"task":"和家长互相说说上周末去过哪里，不必去过远方才有故事。","unitTitle":"过去的周末","releaseId":"grade4-tense-v1","cards":[{"title":"看清时间与结构","example":"Where were you last Sunday?","translation":"你上周日在哪里？","rule":"问过去的位置，把were放到you前面；不是Where did you were。"},{"title":"换一种表达","example":"I was at the library last Sunday.","translation":"我上周日在图书馆。","rule":"last Sunday是已结束的过去时间，描述当时的位置用was，不用am。"},{"title":"上周末，你在哪里","rule":"讲过去在什么地方，用was/were加地点。不要因为出现地点就忘记过去时间；地点介词按整个短语学习，如at home、in the garden。","example":"Sam was at the park.","translation":"Sam当时在公园。"},{"title":"上周末，你在哪里","rule":"讲过去在什么地方，用was/were加地点。不要因为出现地点就忘记过去时间；地点介词按整个短语学习，如at home、in the garden。","example":"We were in the classroom.","translation":"我们当时在教室里。"},{"title":"上周末，你在哪里","rule":"讲过去在什么地方，用was/were加地点。不要因为出现地点就忘记过去时间；地点介词按整个短语学习，如at home、in the garden。","example":"She was at school yesterday.","translation":"她昨天在学校。"}],"itemCount":9,"version":2}'),
('P4A-U02-L3',2,'grade4-tense-v1',4,'A',2,'Was和Were，问答接起来','{"id":"P4A-U02-L3","unitId":"P4A-U02","grade":4,"term":"A","order":7,"unitLesson":3,"unitNumber":2,"minutes":7,"title":"Was和Were，问答接起来","subtitle":"和家长一问一答，说两件昨天的真实情况。","topicIds":["tense.past-simple","sentence.yes-no"],"vocabulary":[{"word":"busy","meaning":"忙碌的"},{"word":"late","meaning":"迟到的"},{"word":"wasn''t","meaning":"was not的缩写"}],"task":"和家长一问一答，说两件昨天的真实情况。","unitTitle":"过去的周末","releaseId":"grade4-tense-v1","cards":[{"title":"看清时间与结构","example":"Was Ben tired yesterday?","translation":"Ben昨天累吗？","rule":"有be的过去问句直接把was提前，不加did。"},{"title":"换一种表达","example":"Yes, he was. No, he was not.","translation":"是的，他累。不是，他不累。","rule":"简短回答保留was；否定可说was not或wasn''t。这里只是两种可能回答，不是同时成立。"},{"title":"Was和Were，问答接起来","rule":"过去的be问句把Was/Were放前面。肯定回答用Yes, 人物代词was/were；否定回答用No, 人物代词wasn''t/weren''t，主语搭配不变。","example":"Was Lily busy? Yes, she was.","translation":"Lily当时忙吗？是的。"},{"title":"Was和Were，问答接起来","rule":"过去的be问句把Was/Were放前面。肯定回答用Yes, 人物代词was/were；否定回答用No, 人物代词wasn''t/weren''t，主语搭配不变。","example":"Were they late? No, they weren''t.","translation":"他们当时迟到了吗？没有。"},{"title":"Was和Were，问答接起来","rule":"过去的be问句把Was/Were放前面。肯定回答用Yes, 人物代词was/were；否定回答用No, 人物代词wasn''t/weren''t，主语搭配不变。","example":"Was Sam at home? No, he wasn''t.","translation":"Sam当时在家吗？不在。"}],"itemCount":9,"version":2}'),
('P4A-U02-L4',2,'grade4-tense-v1',4,'A',2,'写一张周末小卡片','{"id":"P4A-U02-L4","unitId":"P4A-U02","grade":4,"term":"A","order":8,"unitLesson":4,"unitNumber":2,"minutes":7,"title":"写一张周末小卡片","subtitle":"写一张三句周末卡片：什么时候、在哪里、当时感觉怎样。","topicIds":["tense.past-simple"],"vocabulary":[{"word":"weekend","meaning":"周末"},{"word":"quiet","meaning":"安静的"},{"word":"interesting","meaning":"有趣的"}],"task":"写一张三句周末卡片：什么时候、在哪里、当时感觉怎样。","unitTitle":"过去的周末","releaseId":"grade4-tense-v1","cards":[{"title":"看清时间与结构","example":"We were happy at the picnic.","translation":"野餐时我们很开心。","rule":"were描述过去的状态；happy是形容词，不是需要加-ed的动词。"},{"title":"换一种表达","example":"We played a game at the picnic.","translation":"野餐时我们玩了一个游戏。","rule":"played描述做了什么。过去状态用was/were；过去动作一般让实义动词变过去式。"},{"title":"写一张周末小卡片","rule":"过去的小记录可以交代时间、地点和感受。用was/were描述当时状态；如果换成动作动词，要另选合适的过去式，不能在was后直接接动作原形。","example":"I was at a museum on Sunday.","translation":"我周日在一座博物馆。"},{"title":"写一张周末小卡片","rule":"过去的小记录可以交代时间、地点和感受。用was/were描述当时状态；如果换成动作动词，要另选合适的过去式，不能在was后直接接动作原形。","example":"The rooms were quiet.","translation":"房间里很安静。"},{"title":"写一张周末小卡片","rule":"过去的小记录可以交代时间、地点和感受。用was/were描述当时状态；如果换成动作动词，要另选合适的过去式，不能在was后直接接动作原形。","example":"It was an interesting day.","translation":"那是有趣的一天。"}],"itemCount":9,"version":2}'),
('P4A-U03-L1',2,'grade4-tense-v1',4,'A',3,'公园旅行的第一天','{"id":"P4A-U03-L1","unitId":"P4A-U03","grade":4,"term":"A","unitNumber":3,"unitLesson":1,"order":9,"title":"公园旅行的第一天","subtitle":"听一句、找线索，再把句子说清楚","minutes":10,"unitTitle":"有趣的旅行","releaseId":"grade4-tense-v1","cards":[{"title":"看清时间与结构","example":"I visited the park yesterday.","translation":"我昨天参观了公园。","rule":"visit是规则动词，过去式加-ed。yesterday指出已结束的过去时间。"},{"title":"换一种表达","example":"I went to the park yesterday.","translation":"我昨天去了公园。","rule":"go是不规则动词，过去式是went，不能写goed。规则过去式和不规则过去式都能讲过去事件。"},{"title":"公园旅行的第一天","rule":"讲明确过去发生的事情，本组练规则过去式：通常加ed；有些词只加d、变y为ied或双写后加ed。阅读时按原文顺序找时间与行动。","example":"We climbed a hill last Tuesday.","translation":"我们上周二爬了山。"},{"title":"公园旅行的第一天","rule":"讲明确过去发生的事情，本组练规则过去式：通常加ed；有些词只加d、变y为ied或双写后加ed。阅读时按原文顺序找时间与行动。","example":"Owen washed the boots yesterday.","translation":"欧文昨天洗了靴子。"},{"title":"公园旅行的第一天","rule":"讲明确过去发生的事情，本组练规则过去式：通常加ed；有些词只加d、变y为ied或双写后加ed。阅读时按原文顺序找时间与行动。","example":"They played badminton last weekend.","translation":"他们上周末打了羽毛球。"}],"vocabulary":[{"word":"journey","meaning":"旅程"},{"word":"ticket","meaning":"票"},{"word":"path","meaning":"小路"},{"word":"postcard","meaning":"明信片"}],"task":"用听到的内容、原文依据和句子形式完成9个不同目标的小任务。","topicIds":["tense.past-simple"],"itemCount":9,"version":2}'),
('P4A-U03-L2',2,'grade4-tense-v1',4,'A',3,'旅行小帮手','{"id":"P4A-U03-L2","unitId":"P4A-U03","grade":4,"term":"A","unitNumber":3,"unitLesson":2,"order":10,"title":"旅行小帮手","subtitle":"听一句、找线索，再把句子说清楚","minutes":10,"unitTitle":"有趣的旅行","releaseId":"grade4-tense-v1","cards":[{"title":"看清时间与结构","example":"I carried a small bag yesterday.","translation":"我昨天提了一个小包。","rule":"carry以辅音字母加y结尾，变y为i再加-ed，得到carried。"},{"title":"换一种表达","example":"I helped Ben with his bag.","translation":"我帮Ben拿他的包。","rule":"help直接加-ed。不要把carry的变化规则套在所有动词上。"},{"title":"旅行小帮手","rule":"讲明确过去发生的事情，本组练规则过去式：通常加ed；有些词只加d、变y为ied或双写后加ed。阅读时按原文顺序找时间与行动。","example":"We climbed a hill last Tuesday.","translation":"我们上周二爬了山。"},{"title":"旅行小帮手","rule":"讲明确过去发生的事情，本组练规则过去式：通常加ed；有些词只加d、变y为ied或双写后加ed。阅读时按原文顺序找时间与行动。","example":"Owen washed the boots yesterday.","translation":"欧文昨天洗了靴子。"},{"title":"旅行小帮手","rule":"讲明确过去发生的事情，本组练规则过去式：通常加ed；有些词只加d、变y为ied或双写后加ed。阅读时按原文顺序找时间与行动。","example":"They played badminton last weekend.","translation":"他们上周末打了羽毛球。"}],"vocabulary":[{"word":"journey","meaning":"旅程"},{"word":"ticket","meaning":"票"},{"word":"path","meaning":"小路"},{"word":"postcard","meaning":"明信片"}],"task":"用听到的内容、原文依据和句子形式完成9个不同目标的小任务。","topicIds":["tense.past-simple"],"itemCount":9,"version":2}'),
('P4A-U03-L3',2,'grade4-tense-v1',4,'A',3,'雨天也有发现','{"id":"P4A-U03-L3","unitId":"P4A-U03","grade":4,"term":"A","unitNumber":3,"unitLesson":3,"order":11,"title":"雨天也有发现","subtitle":"听一句、找线索，再把句子说清楚","minutes":10,"unitTitle":"有趣的旅行","releaseId":"grade4-tense-v1","cards":[{"title":"看清时间与结构","example":"It rained yesterday morning.","translation":"昨天早上下雨了。","rule":"rain的过去式是rained。这里只报告过去发生的事。"},{"title":"换一种表达","example":"We stayed inside and drew pictures.","translation":"我们待在室内，还画了画。","rule":"stay变stayed；draw变drew。同一个过去故事中，两个动词都要与过去背景一致。"},{"title":"雨天也有发现","rule":"讲明确过去发生的事情，本组练规则过去式：通常加ed；有些词只加d、变y为ied或双写后加ed。阅读时按原文顺序找时间与行动。","example":"We climbed a hill last Tuesday.","translation":"我们上周二爬了山。"},{"title":"雨天也有发现","rule":"讲明确过去发生的事情，本组练规则过去式：通常加ed；有些词只加d、变y为ied或双写后加ed。阅读时按原文顺序找时间与行动。","example":"Owen washed the boots yesterday.","translation":"欧文昨天洗了靴子。"},{"title":"雨天也有发现","rule":"讲明确过去发生的事情，本组练规则过去式：通常加ed；有些词只加d、变y为ied或双写后加ed。阅读时按原文顺序找时间与行动。","example":"They played badminton last weekend.","translation":"他们上周末打了羽毛球。"}],"vocabulary":[{"word":"journey","meaning":"旅程"},{"word":"ticket","meaning":"票"},{"word":"path","meaning":"小路"},{"word":"postcard","meaning":"明信片"}],"task":"用听到的内容、原文依据和句子形式完成9个不同目标的小任务。","topicIds":["tense.past-simple"],"itemCount":9,"version":2}'),
('P4A-U03-L4',2,'grade4-tense-v1',4,'A',3,'整理旅行时间线','{"id":"P4A-U03-L4","unitId":"P4A-U03","grade":4,"term":"A","unitNumber":3,"unitLesson":4,"order":12,"title":"整理旅行时间线","subtitle":"听一句、找线索，再把句子说清楚","minutes":10,"unitTitle":"有趣的旅行","releaseId":"grade4-tense-v1","cards":[{"title":"看清时间与结构","example":"First, we walked to the gate. Then, we saw a bird.","translation":"首先，我们走到大门。然后，我们看见一只鸟。","rule":"First和Then说明顺序；walked是规则过去式，saw是see的不规则过去式。"},{"title":"换一种表达","example":"Did you see the bird?","translation":"你看见那只鸟了吗？","rule":"肯定句用saw，Did问句后还原成see。did已经承担过去时的变化。"},{"title":"整理旅行时间线","rule":"讲明确过去发生的事情，本组练规则过去式：通常加ed；有些词只加d、变y为ied或双写后加ed。阅读时按原文顺序找时间与行动。","example":"We climbed a hill last Tuesday.","translation":"我们上周二爬了山。"},{"title":"整理旅行时间线","rule":"讲明确过去发生的事情，本组练规则过去式：通常加ed；有些词只加d、变y为ied或双写后加ed。阅读时按原文顺序找时间与行动。","example":"Owen washed the boots yesterday.","translation":"欧文昨天洗了靴子。"},{"title":"整理旅行时间线","rule":"讲明确过去发生的事情，本组练规则过去式：通常加ed；有些词只加d、变y为ied或双写后加ed。阅读时按原文顺序找时间与行动。","example":"They played badminton last weekend.","translation":"他们上周末打了羽毛球。"}],"vocabulary":[{"word":"journey","meaning":"旅程"},{"word":"ticket","meaning":"票"},{"word":"path","meaning":"小路"},{"word":"postcard","meaning":"明信片"}],"task":"用听到的内容、原文依据和句子形式完成9个不同目标的小任务。","topicIds":["tense.past-simple"],"itemCount":9,"version":2}'),
('P4A-U04-L1',2,'grade4-tense-v1',4,'A',4,'河边小故事的开头','{"id":"P4A-U04-L1","unitId":"P4A-U04","grade":4,"term":"A","unitNumber":4,"unitLesson":1,"order":13,"title":"河边小故事的开头","subtitle":"听读找线索，分类、改句子，再表达","minutes":12,"releaseId":"grade4-tense-v1","unitTitle":"故事里的发现","cards":[{"title":"看清时间与结构","example":"I saw a little boat by the river.","translation":"我在河边看见了一条小船。","rule":"see → saw → seen。讲这次过去看见的事用saw；不能单独把seen当过去式。"},{"title":"换一种表达","example":"I took a photo of the boat.","translation":"我给那条船拍了一张照片。","rule":"take → took → taken。一般过去时的肯定句选中间一列took。"},{"title":"河边小故事的开头","rule":"说明确过去的完整事件，本组重点看不规则过去式，不能给所有动词直接加ed。阅读和听音先找人物、地点、物品及事件；词形与故事理解分开记录。","example":"I drove to the harbour last month.","translation":"我上个月开车去了海港。"},{"title":"河边小故事的开头","rule":"说明确过去的完整事件，本组重点看不规则过去式，不能给所有动词直接加ed。阅读和听音先找人物、地点、物品及事件；词形与故事理解分开记录。","example":"Eva ran to the bus stop yesterday.","translation":"Eva昨天跑到了公交车站。"},{"title":"河边小故事的开头","rule":"说明确过去的完整事件，本组重点看不规则过去式，不能给所有动词直接加ed。阅读和听音先找人物、地点、物品及事件；词形与故事理解分开记录。","example":"The guide gave Eva a ticket yesterday.","translation":"向导昨天给了Eva一张票。"}],"vocabulary":[{"word":"clue","meaning":"线索"},{"word":"owner","meaning":"主人"},{"word":"compass","meaning":"指南针"},{"word":"carefully","meaning":"小心地"}],"task":"听读找依据，再分类、改一处句子、填词和拼句。是受控练习，不代替自由口语或写作。","topicIds":["tense.past-simple","forms.irregular-past"],"itemCount":9,"version":2}'),
('P4A-U04-L2',2,'grade4-tense-v1',4,'A',4,'迷路的小狗有线索','{"id":"P4A-U04-L2","unitId":"P4A-U04","grade":4,"term":"A","unitNumber":4,"unitLesson":2,"order":14,"title":"迷路的小狗有线索","subtitle":"听读找线索，分类、改句子，再表达","minutes":12,"releaseId":"grade4-tense-v1","unitTitle":"故事里的发现","cards":[{"title":"看清时间与结构","example":"Ben found the dog''s red ball.","translation":"Ben找到了那只狗的红球。","rule":"find的过去式和过去分词都是found。这里直接讲过去的发现，用found。"},{"title":"换一种表达","example":"Did Ben find the red ball?","translation":"Ben找到那个红球了吗？","rule":"Did后用原形find，不能用found；主语换成Ben也不改变这条规则。"},{"title":"迷路的小狗有线索","rule":"说明确过去的完整事件，本组重点看不规则过去式，不能给所有动词直接加ed。阅读和听音先找人物、地点、物品及事件；词形与故事理解分开记录。","example":"I drove to the harbour last month.","translation":"我上个月开车去了海港。"},{"title":"迷路的小狗有线索","rule":"说明确过去的完整事件，本组重点看不规则过去式，不能给所有动词直接加ed。阅读和听音先找人物、地点、物品及事件；词形与故事理解分开记录。","example":"Eva ran to the bus stop yesterday.","translation":"Eva昨天跑到了公交车站。"},{"title":"迷路的小狗有线索","rule":"说明确过去的完整事件，本组重点看不规则过去式，不能给所有动词直接加ed。阅读和听音先找人物、地点、物品及事件；词形与故事理解分开记录。","example":"The guide gave Eva a ticket yesterday.","translation":"向导昨天给了Eva一张票。"}],"vocabulary":[{"word":"clue","meaning":"线索"},{"word":"owner","meaning":"主人"},{"word":"compass","meaning":"指南针"},{"word":"carefully","meaning":"小心地"}],"task":"听读找依据，再分类、改一处句子、填词和拼句。是受控练习，不代替自由口语或写作。","topicIds":["tense.past-simple","forms.irregular-past"],"itemCount":9,"version":2}'),
('P4A-U04-L3',2,'grade4-tense-v1',4,'A',4,'旧箱子里的发现','{"id":"P4A-U04-L3","unitId":"P4A-U04","grade":4,"term":"A","unitNumber":4,"unitLesson":3,"order":15,"title":"旧箱子里的发现","subtitle":"听读找线索，分类、改句子，再表达","minutes":12,"releaseId":"grade4-tense-v1","unitTitle":"故事里的发现","cards":[{"title":"看清时间与结构","example":"I opened the box and found a map.","translation":"我打开盒子，找到了一张地图。","rule":"opened是规则过去式，found是不规则过去式。and连接的两个动作都发生在过去。"},{"title":"换一种表达","example":"I did not find a key in the box.","translation":"我没有在盒子里找到钥匙。","rule":"否定句用did not加原形find，不写did not found。"},{"title":"旧箱子里的发现","rule":"说明确过去的完整事件，本组重点看不规则过去式，不能给所有动词直接加ed。阅读和听音先找人物、地点、物品及事件；词形与故事理解分开记录。","example":"I drove to the harbour last month.","translation":"我上个月开车去了海港。"},{"title":"旧箱子里的发现","rule":"说明确过去的完整事件，本组重点看不规则过去式，不能给所有动词直接加ed。阅读和听音先找人物、地点、物品及事件；词形与故事理解分开记录。","example":"Eva ran to the bus stop yesterday.","translation":"Eva昨天跑到了公交车站。"},{"title":"旧箱子里的发现","rule":"说明确过去的完整事件，本组重点看不规则过去式，不能给所有动词直接加ed。阅读和听音先找人物、地点、物品及事件；词形与故事理解分开记录。","example":"The guide gave Eva a ticket yesterday.","translation":"向导昨天给了Eva一张票。"}],"vocabulary":[{"word":"clue","meaning":"线索"},{"word":"owner","meaning":"主人"},{"word":"compass","meaning":"指南针"},{"word":"carefully","meaning":"小心地"}],"task":"听读找依据，再分类、改一处句子、填词和拼句。是受控练习，不代替自由口语或写作。","topicIds":["tense.past-simple","forms.irregular-past"],"itemCount":9,"version":2}'),
('P4A-U04-L4',2,'grade4-tense-v1',4,'A',4,'把小故事讲完整','{"id":"P4A-U04-L4","unitId":"P4A-U04","grade":4,"term":"A","unitNumber":4,"unitLesson":4,"order":16,"title":"把小故事讲完整","subtitle":"听读找线索，分类、改句子，再表达","minutes":12,"releaseId":"grade4-tense-v1","unitTitle":"故事里的发现","cards":[{"title":"看清时间与结构","example":"I ate a sandwich and drank some water.","translation":"我吃了一个三明治，还喝了些水。","rule":"eat → ate → eaten；drink → drank → drunk。这里报告过去事件，用ate和drank。"},{"title":"换一种表达","example":"I did not eat the cake.","translation":"我没有吃那个蛋糕。","rule":"did not后恢复原形eat。ate、eaten和eat有各自的位置，不能随意互换。"},{"title":"把小故事讲完整","rule":"说明确过去的完整事件，本组重点看不规则过去式，不能给所有动词直接加ed。阅读和听音先找人物、地点、物品及事件；词形与故事理解分开记录。","example":"I drove to the harbour last month.","translation":"我上个月开车去了海港。"},{"title":"把小故事讲完整","rule":"说明确过去的完整事件，本组重点看不规则过去式，不能给所有动词直接加ed。阅读和听音先找人物、地点、物品及事件；词形与故事理解分开记录。","example":"Eva ran to the bus stop yesterday.","translation":"Eva昨天跑到了公交车站。"},{"title":"把小故事讲完整","rule":"说明确过去的完整事件，本组重点看不规则过去式，不能给所有动词直接加ed。阅读和听音先找人物、地点、物品及事件；词形与故事理解分开记录。","example":"The guide gave Eva a ticket yesterday.","translation":"向导昨天给了Eva一张票。"}],"vocabulary":[{"word":"clue","meaning":"线索"},{"word":"owner","meaning":"主人"},{"word":"compass","meaning":"指南针"},{"word":"carefully","meaning":"小心地"}],"task":"听读找依据，再分类、改一处句子、填词和拼句。是受控练习，不代替自由口语或写作。","topicIds":["tense.past-simple","forms.irregular-past"],"itemCount":9,"version":2}'),
('P4B-U02-L1',2,'grade4-tense-v1',4,'B',2,'节日采访用Did提问','{"id":"P4B-U02-L1","unitId":"P4B-U02","grade":4,"term":"B","unitNumber":2,"unitLesson":1,"order":5,"subtitle":"下学期第二站：看清情景、找到依据，再表达自己的想法","minutes":12,"conceptLabIds":["tense.past-simple"],"title":"节日采访用Did提问","releaseId":"grade4-tense-v1","unitTitle":"节日与传统","cards":[{"title":"看清时间与结构","example":"Did you buy a card at the fair?","translation":"你在集市买卡片了吗？","rule":"buy的过去式是bought，但Did问句后用buy，不写bought。"},{"title":"换一种表达","example":"Yes, I did. I bought a blue card.","translation":"是的，我买了。我买了一张蓝色卡片。","rule":"简答用did；接着说肯定的过去事件时，实义动词再用bought。"},{"title":"节日采访用Did提问","rule":"询问过去做没做某事用Did加主语加动词原形。Did承担过去的标记，所以后面不再用过去式。节庆安排均为虚构班级故事。","example":"Did you make lanterns last Friday?","translation":"上周五你做灯笼了吗？"},{"title":"节日采访用Did提问","rule":"询问过去做没做某事用Did加主语加动词原形。Did承担过去的标记，所以后面不再用过去式。节庆安排均为虚构班级故事。","example":"Did Bo visit the class fair?","translation":"Bo参观班级游园会了吗？"},{"title":"节日采访用Did提问","rule":"询问过去做没做某事用Did加主语加动词原形。Did承担过去的标记，所以后面不再用过去式。节庆安排均为虚构班级故事。","example":"Did they carry the paper dragon?","translation":"他们抬纸龙了吗？"}],"vocabulary":[{"word":"lantern","meaning":"灯笼"},{"word":"fair","meaning":"游园会"},{"word":"carry","meaning":"搬；抬"},{"word":"last","meaning":"上一个的"}],"task":"听读找依据，再分类、改一处句子、填词和拼句。是受控练习，不代替自由口语或写作。","topicIds":["tense.past-simple","sentence.negative","sentence.yes-no"],"itemCount":9,"version":2}'),
('P4B-U02-L2',2,'grade4-tense-v1',4,'B',2,'没做的事情用Didn''t','{"id":"P4B-U02-L2","unitId":"P4B-U02","grade":4,"term":"B","unitNumber":2,"unitLesson":2,"order":6,"subtitle":"下学期第二站：看清情景、找到依据，再表达自己的想法","minutes":12,"conceptLabIds":["tense.past-simple"],"title":"没做的事情用Didn''t","releaseId":"grade4-tense-v1","unitTitle":"节日与传统","cards":[{"title":"看清时间与结构","example":"I did not go to the fair.","translation":"我没有去集市。","rule":"did not / didn''t后用go。went只能用于这里对应的肯定过去句。"},{"title":"换一种表达","example":"I went to the museum instead.","translation":"我改去了博物馆。","rule":"没有did的肯定过去句，go要变成went；不要写I go yesterday。"},{"title":"没做的事情用Didn''t","rule":"过去没做某事可用didn''t加动词原形，也可写did not。不要同时把后面的动词写成过去式；这与wasn''t的用法不同。","example":"We didn''t watch the class parade.","translation":"我们没有观看班级巡游。"},{"title":"没做的事情用Didn''t","rule":"过去没做某事可用didn''t加动词原形，也可写did not。不要同时把后面的动词写成过去式；这与wasn''t的用法不同。","example":"Dot did not make the green lantern.","translation":"Dot没有做绿灯笼。"},{"title":"没做的事情用Didn''t","rule":"过去没做某事可用didn''t加动词原形，也可写did not。不要同时把后面的动词写成过去式；这与wasn''t的用法不同。","example":"Bo didn''t bring a paper drum.","translation":"Bo没有带纸鼓。"}],"vocabulary":[{"word":"didn''t","meaning":"过去没有（did not）"},{"word":"parade","meaning":"巡游"},{"word":"drum","meaning":"鼓"},{"word":"ribbon","meaning":"丝带"}],"task":"听读找依据，再分类、改一处句子、填词和拼句。是受控练习，不代替自由口语或写作。","topicIds":["tense.past-simple","sentence.negative","sentence.yes-no"],"itemCount":9,"version":2}'),
('P4B-U02-L3',2,'grade4-tense-v1',4,'B',2,'过去问句怎样简短回应','{"id":"P4B-U02-L3","unitId":"P4B-U02","grade":4,"term":"B","unitNumber":2,"unitLesson":3,"order":7,"subtitle":"下学期第二站：看清情景、找到依据，再表达自己的想法","minutes":12,"conceptLabIds":["tense.past-simple"],"title":"过去问句怎样简短回应","releaseId":"grade4-tense-v1","unitTitle":"节日与传统","cards":[{"title":"看清时间与结构","example":"Did Mia take a photo? Yes, she did.","translation":"Mia拍照片了吗？是的，她拍了。","rule":"Did加原形take提问；简答用she did，不重复took。"},{"title":"换一种表达","example":"Did the boys sing? No, they did not.","translation":"男孩们唱歌了吗？没有。","rule":"一般过去时Did不因主语单复数而变。否定简答也可以说No, they didn''t。"},{"title":"过去问句怎样简短回应","rule":"Did you…?可回答Yes, I did.或No, I didn''t.；Did they…?则用they。简答跟问题的主语和明确的事实一致。","example":"Did you visit the class fair? Yes, I did.","translation":"你参观班级游园会了吗？是的。"},{"title":"过去问句怎样简短回应","rule":"Did you…?可回答Yes, I did.或No, I didn''t.；Did they…?则用they。简答跟问题的主语和明确的事实一致。","example":"Did Dot paint a drum? No, she didn''t.","translation":"Dot画鼓了吗？不，她没有。"},{"title":"过去问句怎样简短回应","rule":"Did you…?可回答Yes, I did.或No, I didn''t.；Did they…?则用they。简答跟问题的主语和明确的事实一致。","example":"Did they dance at the show? Yes, they did.","translation":"他们在表演中跳舞了吗？是的。"}],"vocabulary":[{"word":"reporter","meaning":"记者"},{"word":"interview","meaning":"采访"},{"word":"show","meaning":"表演"},{"word":"dance","meaning":"跳舞"}],"task":"听读找依据，再分类、改一处句子、填词和拼句。是受控练习，不代替自由口语或写作。","topicIds":["tense.past-simple","sentence.negative","sentence.yes-no"],"itemCount":9,"version":2}'),
('P4B-U02-L4',2,'grade4-tense-v1',4,'B',2,'Was与Did不要混在一起','{"id":"P4B-U02-L4","unitId":"P4B-U02","grade":4,"term":"B","unitNumber":2,"unitLesson":4,"order":8,"subtitle":"下学期第二站：看清情景、找到依据，再表达自己的想法","minutes":12,"conceptLabIds":["tense.past-simple"],"title":"Was与Did不要混在一起","releaseId":"grade4-tense-v1","unitTitle":"节日与传统","cards":[{"title":"看清时间与结构","example":"Were you at the show?","translation":"你当时在演出现场吗？","rule":"at the show描述位置，原句是You were…，直接提前were。"},{"title":"换一种表达","example":"Did you watch the show?","translation":"你看了那场演出吗？","rule":"watch是实义动词，过去问句用Did加原形watch。不要写Did you were或Were you watched。"},{"title":"Was与Did不要混在一起","rule":"be动词的过去问句用Was/Were加主语；其他一般过去动作问句用Did加主语加原形。先判断是在问地点或状态，还是在问一个动作。","example":"Was the paper lion beside the stage?","translation":"纸狮子当时在舞台旁吗？"},{"title":"Was与Did不要混在一起","rule":"be动词的过去问句用Was/Were加主语；其他一般过去动作问句用Did加主语加原形。先判断是在问地点或状态，还是在问一个动作。","example":"Were the lanterns in the hall?","translation":"灯笼当时在礼堂里吗？"},{"title":"Was与Did不要混在一起","rule":"be动词的过去问句用Was/Were加主语；其他一般过去动作问句用Did加主语加原形。先判断是在问地点或状态，还是在问一个动作。","example":"Did Bo carry the paper lion?","translation":"Bo抬纸狮子了吗？"}],"vocabulary":[{"word":"was","meaning":"am/is的过去式"},{"word":"were","meaning":"are的过去式"},{"word":"stage","meaning":"舞台"},{"word":"hall","meaning":"礼堂"}],"task":"听读找依据，再分类、改一处句子、填词和拼句。是受控练习，不代替自由口语或写作。","topicIds":["tense.past-simple","sentence.negative","sentence.yes-no"],"itemCount":9,"version":2}'),
('P4B-U05-L1',2,'grade4-tense-v1',4,'B',5,'说说已有的小打算','{"id":"P4B-U05-L1","unitId":"P4B-U05","grade":4,"term":"B","unitNumber":5,"unitLesson":1,"order":17,"subtitle":"下学期第五站：读懂天气、清单与计划，用依据修订表达","minutes":12,"title":"说说已有的小打算","conceptLabIds":["tense.future"],"homeActivity":"给虚构人物画周末计划卡，用am/is/are going to各介绍一项，不需要安排真实外出。","releaseId":"grade4-tense-v1","unitTitle":"周末将要做什么","cards":[{"title":"看清时间与结构","example":"I am going to make a model tomorrow.","translation":"我打算明天做一个模型。","rule":"已有的打算可用be going to加原形make；主语I搭配am。"},{"title":"换一种表达","example":"Ben is going to make a model tomorrow.","translation":"Ben打算明天做一个模型。","rule":"主语改成Ben，be改成is，make仍是原形。不要因tomorrow把make变成过去式。"},{"title":"说说已有的小打算","rule":"be going to加动词原形可以表达打算：I am going to draw。be随主语用am/is/are，going to后不再加动词ing。本课是计划，不表示活动已经完成，也不保证计划不会变。","example":"I am going to make a paper kite.","translation":"我打算做一只纸风筝。"},{"title":"说说已有的小打算","rule":"be going to加动词原形可以表达打算：I am going to draw。be随主语用am/is/are，going to后不再加动词ing。本课是计划，不表示活动已经完成，也不保证计划不会变。","example":"Suri is going to draw a map.","translation":"Suri打算画地图。"},{"title":"说说已有的小打算","rule":"be going to加动词原形可以表达打算：I am going to draw。be随主语用am/is/are，going to后不再加动词ing。本课是计划，不表示活动已经完成，也不保证计划不会变。","example":"We are going to visit the model room.","translation":"我们打算参观模型室。"}],"vocabulary":[{"word":"plan","meaning":"计划"},{"word":"going to","meaning":"打算；将要"},{"word":"prepare","meaning":"准备"},{"word":"weekend","meaning":"周末"}],"task":"听读找依据，再分类、改一处句子、填词和拼句。是受控练习，不代替自由口语或写作。","topicIds":["tense.future","grammar.be","sentence.yes-no"],"itemCount":9,"version":2}'),
('P4B-U05-L2',2,'grade4-tense-v1',4,'B',5,'计划里暂时不做什么','{"id":"P4B-U05-L2","unitId":"P4B-U05","grade":4,"term":"B","unitNumber":5,"unitLesson":2,"order":18,"subtitle":"下学期第五站：读懂天气、清单与计划，用依据修订表达","minutes":12,"title":"计划里暂时不做什么","conceptLabIds":["tense.future"],"homeActivity":"在纸上修改一项虚构计划，用isn''t或aren''t going to说明暂时不做什么，不把它说成禁止。","releaseId":"grade4-tense-v1","unitTitle":"周末将要做什么","cards":[{"title":"看清时间与结构","example":"We are not going to swim tomorrow.","translation":"我们不打算明天游泳。","rule":"be going to的否定把not放在be后；We搭配are。"},{"title":"换一种表达","example":"We will not swim tomorrow.","translation":"我们明天不会游泳。","rule":"will not也能表达将来的否定。will后用原形，不写will swam；两种结构不机械地等于相同语境。"},{"title":"计划里暂时不做什么","rule":"把not放在be后：is not going to、are not going to。isn''t/aren''t是对应缩写；本课I am not不缩成I amn''t。这里表达没有这个打算，不代表禁止或永远不会做。","example":"I am not going to paint the lid today.","translation":"我今天不打算给盖子涂色。"},{"title":"计划里暂时不做什么","rule":"把not放在be后：is not going to、are not going to。isn''t/aren''t是对应缩写；本课I am not不缩成I amn''t。这里表达没有这个打算，不代表禁止或永远不会做。","example":"Riko isn''t going to use the large box.","translation":"Riko不打算用大盒子。"},{"title":"计划里暂时不做什么","rule":"把not放在be后：is not going to、are not going to。isn''t/aren''t是对应缩写；本课I am not不缩成I amn''t。这里表达没有这个打算，不代表禁止或永远不会做。","example":"They aren''t going to finish the model tonight.","translation":"他们不打算今晚完成模型。"}],"vocabulary":[{"word":"not","meaning":"不"},{"word":"lid","meaning":"盖子"},{"word":"tonight","meaning":"今晚"},{"word":"instead","meaning":"代替；反而"}],"task":"听读找依据，再分类、改一处句子、填词和拼句。是受控练习，不代替自由口语或写作。","topicIds":["tense.future","grammar.be","sentence.yes-no"],"itemCount":9,"version":2}'),
('P4B-U05-L3',2,'grade4-tense-v1',4,'B',5,'用be开头问计划','{"id":"P4B-U05-L3","unitId":"P4B-U05","grade":4,"term":"B","unitNumber":5,"unitLesson":3,"order":19,"subtitle":"下学期第五站：读懂天气、清单与计划，用依据修订表达","minutes":12,"title":"用be开头问计划","conceptLabIds":["tense.future"],"homeActivity":"和愿意参与的家人用Are you going to…?问一个纸上计划，如实角色回答，不要求真实承诺。","releaseId":"grade4-tense-v1","unitTitle":"周末将要做什么","cards":[{"title":"看清时间与结构","example":"Is Ben going to bring a ball?","translation":"Ben打算带一个球来吗？","rule":"be going to问句把be提前；bring仍用原形。"},{"title":"换一种表达","example":"Will Ben bring a ball?","translation":"Ben会带一个球来吗？","rule":"will问句把will提前。两种问法都不能把bring写成过去式brought。"},{"title":"用be开头问计划","rule":"询问计划时把be移到主语前：Are you going to…? 后面仍用原形。Yes, I am和No, I''m not对应Are you…?；问Are they…?则用they are或they aren''t。","example":"Are you going to draw a poster?","translation":"你打算画海报吗？"},{"title":"用be开头问计划","rule":"询问计划时把be移到主语前：Are you going to…? 后面仍用原形。Yes, I am和No, I''m not对应Are you…?；问Are they…?则用they are或they aren''t。","example":"Yes, I am.","translation":"是的，我打算。"},{"title":"用be开头问计划","rule":"询问计划时把be移到主语前：Are you going to…? 后面仍用原形。Yes, I am和No, I''m not对应Are you…?；问Are they…?则用they are或they aren''t。","example":"Is she going to bring a notebook?","translation":"她打算带笔记本吗？"}],"vocabulary":[{"word":"rehearse","meaning":"排练"},{"word":"notebook","meaning":"笔记本"},{"word":"invite","meaning":"邀请"},{"word":"reply","meaning":"回答"}],"task":"听读找依据，再分类、改一处句子、填词和拼句。是受控练习，不代替自由口语或写作。","topicIds":["tense.future","grammar.be","sentence.yes-no"],"itemCount":9,"version":2}'),
('P4B-U05-L4',2,'grade4-tense-v1',4,'B',5,'看计划表，不猜结果','{"id":"P4B-U05-L4","unitId":"P4B-U05","grade":4,"term":"B","unitNumber":5,"unitLesson":4,"order":20,"subtitle":"下学期第五站：读懂天气、清单与计划，用依据修订表达","minutes":12,"title":"看计划表，不猜结果","conceptLabIds":["tense.future"],"homeActivity":"写两项虚构计划，在旁边标记尚未发生；练习说明计划和完成记录有什么不同。","releaseId":"grade4-tense-v1","unitTitle":"周末将要做什么","cards":[{"title":"看清时间与结构","example":"The plan says we are going to meet at ten.","translation":"计划写着我们打算十点见面。","rule":"计划表说明意图，不证明事情必然已经发生。这里meet用原形。"},{"title":"换一种表达","example":"Yesterday, we met at ten.","translation":"昨天，我们十点见了面。","rule":"叙述已发生的过去事实时，meet变成met。时间背景改变，动词结构也改变。"},{"title":"看计划表，不猜结果","rule":"计划表写打算做什么，不证明事情已经发生。找人物、日期和动作后再用be going to表达；如果日期或完成结果没写，就不能自己补上。","example":"The note says we are going to meet on Tuesday.","translation":"便条说我们打算周二见面。"},{"title":"看计划表，不猜结果","rule":"计划表写打算做什么，不证明事情已经发生。找人物、日期和动作后再用be going to表达；如果日期或完成结果没写，就不能自己补上。","example":"It does not say that we have met already.","translation":"它没说我们已经见过面。"},{"title":"看计划表，不猜结果","rule":"计划表写打算做什么，不证明事情已经发生。找人物、日期和动作后再用be going to表达；如果日期或完成结果没写，就不能自己补上。","example":"Our plan may change.","translation":"我们的计划可能改变。"}],"vocabulary":[{"word":"date","meaning":"日期"},{"word":"result","meaning":"结果"},{"word":"already","meaning":"已经"},{"word":"change","meaning":"改变"}],"task":"听读找依据，再分类、改一处句子、填词和拼句。是受控练习，不代替自由口语或写作。","topicIds":["tense.future","grammar.be","sentence.yes-no"],"itemCount":9,"version":2}'),
('P4B-U06-L1',2,'grade4-tense-v1',4,'B',6,'昨天发生的小故事','{"id":"P4B-U06-L1","unitId":"P4B-U06","grade":4,"term":"B","unitNumber":6,"unitLesson":1,"order":21,"subtitle":"下学期第六站：整理作品，按依据表达，再安排后续复习","minutes":12,"title":"昨天发生的小故事","homeActivity":"给虚构角色画一个已结束的小经历，标出过去时间，先写肯定句，再试着用Did提问。无需回忆或公开自己的真实经历。","conceptLabIds":["tense.past-simple"],"releaseId":"grade4-tense-v1","unitTitle":"我的故事展","cards":[{"title":"看清时间与结构","example":"Yesterday, I wrote a postcard.","translation":"昨天，我写了一张明信片。","rule":"已结束的过去事件用wrote。write → wrote → written，written不能单独替代wrote。"},{"title":"换一种表达","example":"I did not write an email yesterday.","translation":"我昨天没有写电子邮件。","rule":"同样是昨天的事情，否定句里由did承担过去变化，write还原。"},{"title":"昨天发生的小故事","rule":"讲昨天已结束的动作，肯定句用一般过去时；did或didn''t后面的主要动词用原形。过去时间词提供线索，但也要读整句，不把一次经历当成经常发生的事。","example":"Yesterday, Nima folded a card whale.","translation":"昨天Nima折了一只卡纸鲸鱼。"},{"title":"昨天发生的小故事","rule":"讲昨天已结束的动作，肯定句用一般过去时；did或didn''t后面的主要动词用原形。过去时间词提供线索，但也要读整句，不把一次经历当成经常发生的事。","example":"Did you carry the model gate?","translation":"你搬了模型大门吗？"},{"title":"昨天发生的小故事","rule":"讲昨天已结束的动作，肯定句用一般过去时；did或didn''t后面的主要动词用原形。过去时间词提供线索，但也要读整句，不把一次经历当成经常发生的事。","example":"We didn''t use real candles at the show.","translation":"我们在展览上没有用真蜡烛。"}],"vocabulary":[{"word":"yesterday","meaning":"昨天"},{"word":"folded","meaning":"折了"},{"word":"carried","meaning":"搬了"},{"word":"finished","meaning":"完成了"}],"task":"听读找依据，再分类、改一处句子、填词和拼句。是受控练习，不代替自由口语或写作。","topicIds":["tense.past-simple","tense.present-continuous","tense.future"],"itemCount":9,"version":2}'),
('P4B-U06-L2',2,'grade4-tense-v1',4,'B',6,'现在镜头里发生什么','{"id":"P4B-U06-L2","unitId":"P4B-U06","grade":4,"term":"B","unitNumber":6,"unitLesson":2,"order":22,"subtitle":"下学期第六站：整理作品，按依据表达，再安排后续复习","minutes":12,"title":"现在镜头里发生什么","homeActivity":"给虚构故事画一张现在的镜头和一张每周习惯卡，用现在进行时和一般现在时分别配文。可以先用中文解释时间差别。","conceptLabIds":["tense.present-contrast"],"releaseId":"grade4-tense-v1","unitTitle":"我的故事展","cards":[{"title":"看清时间与结构","example":"I usually draw after school.","translation":"我通常放学后画画。","rule":"usually说明习惯，用一般现在时；I后用draw。"},{"title":"换一种表达","example":"Look! I am drawing a dragon now.","translation":"看！我现在正在画一条龙。","rule":"此刻正在进行，用am drawing；不是I drawing，也不是I drew now。"},{"title":"现在镜头里发生什么","rule":"am/is/are加动词ing表示此刻正在进行的动作；第三人称单数一般现在时常用动词s。now与every Friday指向不同时间，选择时还要看主语。","example":"I am drawing a paper observatory now.","translation":"我现在正在画一座纸天文台。"},{"title":"现在镜头里发生什么","rule":"am/is/are加动词ing表示此刻正在进行的动作；第三人称单数一般现在时常用动词s。now与every Friday指向不同时间，选择时还要看主语。","example":"The helpers are fixing a toy sign.","translation":"帮手们正在修玩具标牌。"},{"title":"现在镜头里发生什么","rule":"am/is/are加动词ing表示此刻正在进行的动作；第三人称单数一般现在时常用动词s。now与every Friday指向不同时间，选择时还要看主语。","example":"Fara checks the model train every Friday.","translation":"Fara每星期五检查模型火车。"}],"vocabulary":[{"word":"now","meaning":"现在"},{"word":"fixing","meaning":"正在修理"},{"word":"checking","meaning":"正在检查"},{"word":"usually","meaning":"通常"}],"task":"听读找依据，再分类、改一处句子、填词和拼句。是受控练习，不代替自由口语或写作。","topicIds":["tense.past-simple","tense.present-continuous","tense.future"],"itemCount":9,"version":2}'),
('P4B-U06-L3',2,'grade4-tense-v1',4,'B',6,'给故事写一个计划','{"id":"P4B-U06-L3","unitId":"P4B-U06","grade":4,"term":"B","unitNumber":6,"unitLesson":3,"order":23,"subtitle":"下学期第六站：整理作品，按依据表达，再安排后续复习","minutes":12,"title":"给故事写一个计划","homeActivity":"给纸上故事写一条明确标为计划的结尾，说明它尚未完成。可以用isn''t或aren''t改计划，不把计划当作必须兑现的承诺。","conceptLabIds":["tense.future"],"releaseId":"grade4-tense-v1","unitTitle":"我的故事展","cards":[{"title":"看清时间与结构","example":"I drew a dragon yesterday.","translation":"我昨天画了一条龙。","rule":"昨天的画已经是过去事件，draw用过去式drew。"},{"title":"换一种表达","example":"I am going to draw a robot tomorrow.","translation":"我打算明天画一个机器人。","rule":"明天的打算用am going to加原形draw。过去、现在、将来的背景不要混在一个结构里。"},{"title":"给故事写一个计划","rule":"be going to加动词原形表达计划，am/is/are与主语一致。计划不等于保证，也不等于已经完成；否定可以用is not/isn''t或are not/aren''t。","example":"I am going to add a paper window.","translation":"我打算加一扇纸窗。"},{"title":"给故事写一个计划","rule":"be going to加动词原形表达计划，am/is/are与主语一致。计划不等于保证，也不等于已经完成；否定可以用is not/isn''t或are not/aren''t。","example":"They are going to revise the final caption.","translation":"他们打算修改最后一条配文。"},{"title":"给故事写一个计划","rule":"be going to加动词原形表达计划，am/is/are与主语一致。计划不等于保证，也不等于已经完成；否定可以用is not/isn''t或are not/aren''t。","example":"She isn''t going to share the private draft.","translation":"她不打算分享那份私人草稿。"}],"vocabulary":[{"word":"plan","meaning":"计划"},{"word":"tomorrow","meaning":"明天"},{"word":"revise","meaning":"修改"},{"word":"draft","meaning":"草稿"}],"task":"听读找依据，再分类、改一处句子、填词和拼句。是受控练习，不代替自由口语或写作。","topicIds":["tense.past-simple","tense.present-continuous","tense.future"],"itemCount":9,"version":2}'),
('P4B-U06-L4',2,'grade4-tense-v1',4,'B',6,'一封有时间线索的短信','{"id":"P4B-U06-L4","unitId":"P4B-U06","grade":4,"term":"B","unitNumber":6,"unitLesson":4,"order":24,"subtitle":"下学期第六站：整理作品，按依据表达，再安排后续复习","minutes":12,"title":"一封有时间线索的短信","homeActivity":"给虚构朋友写三句纸上短信：一件过去的事、现在的情况、一个未来计划。可以先列中文时间线；本活动不提交、不自动评分，也不发送消息。","conceptLabIds":["tense.past-simple","tense.future"],"releaseId":"grade4-tense-v1","unitTitle":"我的故事展","cards":[{"title":"看清时间与结构","example":"Yesterday I swam. Now I am resting.","translation":"昨天我游了泳。现在我正在休息。","rule":"同一段文字可以换时间：yesterday配swam，now配am resting，各句各自有明确背景。"},{"title":"换一种表达","example":"Tomorrow I will swim again.","translation":"明天我会再去游泳。","rule":"will后用原形swim。swim、swam、swum是词形；过去式和过去分词不是两种独立的时间。"},{"title":"一封有时间线索的短信","rule":"一封故事短信可以先写已发生的经历，再说现在的情况，最后写计划。First/Next/Finally帮助说明顺序，because说明原因。先读时间和因果，不只靠关键词机械换时态。","example":"Yesterday, we drew a map of the clay town.","translation":"昨天我们画了粘土小镇地图。"},{"title":"一封有时间线索的短信","rule":"一封故事短信可以先写已发生的经历，再说现在的情况，最后写计划。First/Next/Finally帮助说明顺序，because说明原因。先读时间和因果，不只靠关键词机械换时态。","example":"Now we are checking the street names.","translation":"现在我们正在检查街道名称。"},{"title":"一封有时间线索的短信","rule":"一封故事短信可以先写已发生的经历，再说现在的情况，最后写计划。First/Next/Finally帮助说明顺序，because说明原因。先读时间和因果，不只靠关键词机械换时态。","example":"Tomorrow, we are going to add a title.","translation":"明天我们打算加一个标题。"}],"vocabulary":[{"word":"first","meaning":"首先"},{"word":"next","meaning":"接着"},{"word":"finally","meaning":"最后"},{"word":"because","meaning":"因为"}],"task":"听读找依据，再分类、改一处句子、填词和拼句。是受控练习，不代替自由口语或写作。","topicIds":["tense.past-simple","tense.present-continuous","tense.future"],"itemCount":9,"version":2}'),
